/bin/zsh -lc "command -v dev-browser
dev-browser --headless --timeout 45 <<'EOF'
const page = await browser.getPage(\"hvac-exhibit\");
await page.setViewportSize({ width: 1440, height: 960 });
await page.goto(\"file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/air-conditioning-understanding/2026-07-14-codex-gpt-5-6-sol-2/index.html\", { waitUntil: \"load\", timeout: 30000 });
await page.waitForTimeout(12000);
const result = await page.evaluate(() => ({
  title: document.title,
  h1: document.querySelector('h1')?.textContent,
  ready: document.body.classList.contains('webgl-ready'),
  fallback: document.querySelector('#fallback')?.classList.contains('visible'),
  canvas: { width: document.querySelector('canvas')?.width, height: document.querySelector('canvas')?.height },
  controls: [...document.querySelectorAll('button')].map(b => ({ text: b.textContent.trim(), label: b.getAttribute('aria-label'), pressed: b.getAttribute('aria-pressed') }))
}));
console.log(JSON.stringify(result, null, 2));
EOF"

